DROP TABLE IF EXISTS `coding_submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `coding_submissions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `problem_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contest_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `language` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('AC','WA','TLE','CE','RE','PENDING') COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  `score` int(11) DEFAULT '0',
  `time_used` int(11) DEFAULT '0',
  `memory_used` int(11) DEFAULT '0',
  `submitted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `problem_id` (`problem_id`) USING BTREE,
  KEY `idx_user_problem` (`user_id`,`problem_id`) USING BTREE,
  KEY `idx_contest` (`contest_id`,`submitted_at`) USING BTREE,
  CONSTRAINT `coding_submissions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `coding_submissions_ibfk_2` FOREIGN KEY (`problem_id`) REFERENCES `problems` (`id`) ON DELETE CASCADE,
  CONSTRAINT `coding_submissions_ibfk_3` FOREIGN KEY (`contest_id`) REFERENCES `contests` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码提交记录';
