rintln(\"3 雷洞坪车站——金顶          距离：13333(米) 票价：3元(金币)\");\n    }\n}','CE',0,0,0,'2026-03-12 07:17:40'),(110,'s001','p1773574726849311',NULL,'cpp','#include <iostream>\n#include<string>\n#include<algorithm>\n#include<vector>\nusing namespace std;\nint q;\n\nint main() \n{\n    cin >> q;\n\n    while(q--)\n    {\n        int s;\n        bool is = false;\n        cin >> s;\n\n        if(s % 2 == 0)\n        {\n            cout << s << endl;\n            is = true;\n            continue;\n        }\n        else \n        {\n            vector<int> num;\n            bool is1 = false;\n            while(s > 0)\n            {\n                int temp = s % 10;\n                num.push_back(temp);\n                s /= 10;\n            }\n            int len = num.size();\n            for(int i = 0;i <num.size();++i)\n            {\n                if(num[i] % 2 == 0)\n                {\n                    swap(num[i] , num[len - 1]);\n                    is1 = true;\n                    is = true;\n                    break;\n                }\n            }\n\n            if(is1)\n            {\n                for(int i = 0;i < num.size();++i)\n                {\n                    cout << num[i];\n                }\n                cout << endl;\n            }\n\n            \n            \n        }\n\n        if(!is)\n        {\n            cout << -1 << endl;\n        }\n\n    }    \n    \n}\n// 64 位输出请用 printf(\"%lld\")\n','TLE',50,308,30,'2026-03-15 15:10:29'),(111,'253030007','p1773573888682859',NULL,'java','import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        // Write Java code here\n        Scanner sc=new Scanner(System.in);\n        String e=sc.next();\n        String a=sc.next();\n        System.out.println(e+a);\n         \n    }\n}','AC',100,2686,27,'2026-03-23 04:22:05'),(112,'253250451','p1772984532066150',NULL,'python','def main():\n    # Write Python code here\n    print(\"Hello World!\")\n\nif __name__