INSERT INTO `problem_banks` VALUES ('b1772983110409','Java基础训练','Java基础语法练习',NULL,'2026-03-08 15:18:30'),('b1772983185725','传智杯初赛题库','',NULL,'2026-03-08 15:19:45'),('b1772983197908','蓝桥杯题库','',NULL,'2026-03-08 15:19:57'),('bank_c_basic','C语言基础训练1','面向初学者的C语言基础语法练习题','https://placehold.co/600x400?text=C','2026-01-19 01:27:01');
