DROP TABLE IF EXISTS `problems`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `problems` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目ID',
  `bank_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` enum('Easy','Medium','Hard') COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_example` text COLLATE utf8mb4_unicode_ci,
  `output_example` text COLLATE utf8mb4_unicode_ci,
  `tags` json DEFAULT NULL,
  `pass_rate` decimal(5,2) DEFAULT '0.00',
  `reference_code` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_bank_difficulty` (`bank_id`,`difficulty`) USING BTREE,
  FULLTEXT KEY `idx_title_search` (`title`),
  CONSTRAINT `problems_ibfk_1` FOREIGN KEY (`bank_id`) REFERENCES `problem_banks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='题目表';
